-- =============================================================================
-- DeuTime — Seed de desenvolvimento
-- Popula três times fictícios com atletas suficientes para 4 times em cada:
--   - Campo FC:       44 atletas (11 por time × 4)
--   - Society United: 28 atletas ( 7 por time × 4)
--   - Futsal Raio:    20 atletas ( 5 por time × 4)
-- Execute depois de `supabase db reset`.
-- =============================================================================

set session_replication_role = replica;

-- -----------------------------------------------------------------------------
-- Usuário admin — criado pelo script: npm run db:seed-user
-- O script usa a Admin API para criar o usuário em auth.users com UUID fixo.
-- O trigger handle_new_user cria o profile automaticamente.
-- SEED_USER_ID: 00000000-0000-0000-0000-000000000001
-- NÃO inserir em auth.users nem em profiles aqui.
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Times
-- -----------------------------------------------------------------------------
